# Check if there's more detailed data in the JSON file
import json
with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

# Search for tables with individual income tax data
def find_tables(d, path=""):
    if isinstance(d, dict):
        for k, v in d.items():
            find_tables(v, f"{path}.{k}")
    elif isinstance(d, list):
        for i, item in enumerate(d):
            find_tables(item, f"{path}[{i}]")

# Let's look for "individual" key
print("Searching for individual income tax data...")
for key in data.keys():
    print(f"Key: {key}")

# Check if there's a table structure
if 'table' in str(type(data)):
    print("Found table")
